static int rd_i32(vm_rd_t*r,int32_t*v){uint32_t q;if(!r||r->e-r->p<4)return 0;q=(uint32_t)r->p[0]|((uint32_t)r->p[1]<<8)|((uint32_t)r->p[2]<<16)|((uint32_t)r->p[3]<<24);r->p+=4;*v=(int32_t)q;return 1;}
